// v5: L2 cache controller (L2C) MMIO register block. Memory-mapped at L2C base
// 0xE0500000 (DS220 24.2). The documented register window spans offset
// 0x0000..0x0527 (DS220 11.8.5 Table 112, Number of Processor Cores 1-4). The
// WHOLE window is captured verbatim (little-endian, native RV64/x86-64) so the
// drained record is complete and --verify-able; `reg[off/8]` is the 64-bit
// register at byte offset `off`. Live only when HYBRID_FLAG_L2C is set.
//
// On resume, ResumeDriver writes back ONLY the boot-static WRITABLE config
// registers listed below. Everything else in the window is captured but never
// restored, because writing it is wrong or unsafe:
//   - Configuration Register (0x0000): read-only, derived from the build.
//   - CCTL Command Registers (0x0040..0x007f): writing one RE-ISSUES an L2 cache
//     flush/invalidate -- restoring a stale command would kick off a cache op at
//     ROI entry.
//   - Asynchronous/Error Registers (0x0030..0x003f): write-1-clear status.
//   - CCTL Status (0x0080), HPM Counters (0x0200..0x020f): read-only / volatile.
#define HYBRID_L2C_REG_WINDOW_BYTES  0x528u              /* 0x0000..0x0527 */
#define HYBRID_L2C_REG_WINDOW_QWORDS (0x528u / 8u)       /* 165 * uint64_t = 1320 B */

// Writable boot-static config register offsets restored on resume (DS220 11.8.7 /
// 11.8.8 / 11.8.17). Each is a 64-bit register the hart accesses 4 bytes at a time
// (DS220 11.8.3: single transfer, access size < 8 bytes, device non-bufferable).
#define HYBRID_L2C_OFF_CONTROL   0x0008u  /* CEN enable + PFTHRES + ECCEN + RAM timing */
#define HYBRID_L2C_OFF_HPM_CTL0  0x0010u  /* HPM Control Register 0 (event select) */
#define HYBRID_L2C_OFF_WAYMASK0  0x0300u  /* Way Allocation Mask Register 0 */
#define HYBRID_L2C_WAYMASK_NUM   5u       /* masks 0..4 @ 0x0300,0x0308,..,0x0320 (cores 1-4) */

struct hybrid_l2c {
  uint64_t reg[HYBRID_L2C_REG_WINDOW_QWORDS];  // reg[off/8] = register @ byte offset off
};

// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
// unnecessary and would force unaligned access codegen. Layout is locked by
// the static_asserts in state_abi_check.h.
struct hybrid_state_v1 {
  uint32_t magic;
  uint32_t version;
  uint32_t flags;
  uint32_t hart_id;
  uint64_t pc;
  uint64_t priv;  // 0=U, 1=S, 3=M

  uint64_t gpr[32];
  uint64_t fpr[32];

  uint64_t mstatus;
  uint64_t mepc;
  uint64_t mtvec;
  uint64_t mcause;
  uint64_t mtval;
  uint64_t mscratch;
  uint64_t medeleg;
  uint64_t mideleg;
  uint64_t mip;
  uint64_t mie;
  uint64_t mcycle;
  uint64_t minstret;
  uint64_t satp;

  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];

  uint64_t vstart;
  uint64_t vtype;
  uint64_t vl;
  uint64_t vlenb;
  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
  uint64_t vxsat;
  uint64_t vxrm;
  uint64_t vcsr;

  // L20: FP control/status -- frm[7:5] | fflags[4:0], live when
  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
  // re-read by StateDrain. Pre-L20 state files carry 0 here (reserved bytes
  // are written as zero), which reads back as the reset value (RNE, no
  // flags) -- exactly the old behavior, so no version bump.
  uint64_t fcsr;

  // Andes machine-setup CSRs: mcache_ctl (0x7CA) enables the L1 I/D caches,
  // mmisc_ctl (0x7D0) holds misc machine config. crt0 writes them once at
  // boot; transporting them keeps the cycle engine from resuming caches-off
  // (ResumeDriver has the full rationale). Drained by the plugin, restored by
  // ResumeDriver, but NOT re-read by StateDrain: they are boot-static and the
  // drained value is unused (no QEMU2 leg). Old state files carry 0 here
  // (reset value), which is the pre-existing behavior, so no version bump.
  uint64_t mcache_ctl;
  uint64_t mmisc_ctl;

  // v3: Andes V5 CSR block (live when HYBRID_FLAG_ANDES). 31 * 8 = 248 bytes.
  struct hybrid_andes_csr andes;

  // v4: writable M-mode CSR block (live when HYBRID_FLAG_M_EXT). 51 * 8 = 408
  // bytes. Capability-gated per engine; transported forward-looking.
  struct hybrid_m_ext_csr m_ext;

  // v5: L2C MMIO register window (live when HYBRID_FLAG_L2C). 165 * 8 = 1320
  // bytes. Capability-gated on the engine having an L2C; transported
  // forward-looking. Whole window captured; only writable config restored.
  struct hybrid_l2c l2c;

  uint8_t  reserved[64];  // zero-initialise on write; v5-compatible growth room
};

