        memcpy(&s.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8], l2c->data,
               sizeof(uint64_t));
        s.flags |= HYBRID_FLAG_L2C;
    }
}

if (write_state_atomic(&s, outfile_path) != 0) {

    HYBRID_M_EXT_CSR_LIST(X)
#undef X
  }

  // L2C MMIO config (v5, minimal): only the L2C Control Register is drained so
  // far; it round-trips (restored at resume, re-read at drain), so compare its
  // RW config bits (CEN, prefetch, ECC, RAM timing). INITSTATUS[14] is a
  // read-only status bit -- a real L2C model drives it, QEMU's RAM stub does
  // not -- so mask it to avoid a false positive.
  if (ref.flags & HYBRID_FLAG_L2C) {
    const uint64_t rw_mask = ~(uint64_t{1} << 14);  // clear INITSTATUS[14]
    cmp(r, "l2c.ctrl",
        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask,
        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask);
  }

  return r;
}

